o cuadro?', '[{"label":"A","text":"Hace una pregunta a la profesora.","is_correct":false,"distractor_type":"Inventa una acción.","explanation_feedback":"Incorrecta. Camilo no dice nada."},{"label":"B","text":"Tiene la cámara apagada y no responde.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Su globo solo muestra puntos suspensivos."},{"label":"C","text":"Explica el tema a sus compañeros.","is_correct":false,"distractor_type":"Inventa una acción.","explanation_feedback":"Incorrecta. No habla."},{"label":"D","text":"Se despide de la clase.","is_correct":false,"distractor_type":"Inventa una acción.","explanation_feedback":"Incorrecta. No hay despedida."}]'::jsonb, null, 0.9, -1.2, 0.25, 45, 'original_generated'
